INSERT INTO blogs (id, document_id, title, slug, short_description, type, content,
  created_at, updated_at, published_at, locale, meta_title, meta_description,
  focus_keyphrase, canonical_url, robots_directive, reading_time_minutes)
VALUES (
  (SELECT COALESCE(MAX(id),0)+1 FROM blogs),
  lower(hex(randomblob(16))),
  'Asam Humat: Panduan Lengkap (Pengertian, Manfaat, Dosis & Produk)',
  'panduan-lengkap-asam-humat',
  'Panduan lengkap asam humat: pengertian, sumber, cara kerja, manfaat, dosis, aplikasi per komoditas, dan cara memilih asam humat cair yang baik.',
  'blog',
  '[{"type": "paragraph", "children": [{"type": "text", "text": "Asam humat adalah senyawa organik alami hasil dekomposisi bahan organik yang berfungsi sebagai pembenah tanah. Panduan lengkap ini merangkum pengertian, sumber, cara kerja, manfaat, dosis, aplikasi per komoditas, hingga cara memilih asam humat cair yang baik."}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Apa Itu Asam Humat?"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Asam humat adalah senyawa organik kompleks yang terbentuk secara alami dari dekomposisi bahan organik seperti sisa tanaman, hewan, dan mikroba melalui proses humifikasi. Senyawa ini merupakan komponen utama humus, yaitu fraksi organik tanah yang stabil dan berperan penting dalam meningkatkan kesuburan tanah."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Proses humifikasi melibatkan transformasi biokimia bahan organik oleh mikroorganisme tanah, menghasilkan molekul humat dengan berat molekul tinggi dan gugus fungsional seperti karboksil dan fenol. Struktur ini memberikan asam humat kemampuan untuk berinteraksi dengan mineral tanah, logam, dan nutrisi."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Sebagai pembenah tanah, asam humat bekerja secara fisik, kimia, dan biologis. Secara fisik, ia memperbaiki struktur tanah, meningkatkan porositas, dan retensi air. Secara kimia, ia meningkatkan kapasitas tukar kation (KTK), mengkhelat logam, dan menyangga pH tanah. Secara biologis, ia merangsang aktivitas mikroba akar dan meningkatkan ketersediaan hara bagi tanaman."}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Asam Humat Terbuat dari Apa? Sumber dan Ekstraksi"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Asam humat diperoleh dari bahan organik yang telah mengalami proses humifikasi selama jutaan tahun. Sumber utama asam humat adalah leonardite, yaitu batuan organik yang kaya akan humus dan terbentuk dari oksidasi alami batu bara lignit. Selain itu, gambut dan batu bara muda (lignit) juga merupakan sumber yang umum digunakan karena kandungan senyawa humat yang tinggi."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Proses ekstraksi asam humat umumnya dimulai dengan menghancurkan bahan baku menjadi partikel halus, kemudian direaksikan dengan larutan alkali seperti kalium hidroksida atau natrium hidroksida. Reaksi ini melarutkan asam humat dan membentuk garam humat yang larut dalam air. Setelah penyaringan dan pemurnian, diperoleh ekstrak cair yang mengandung asam humat dalam bentuk aktif dan siap diaplikasikan sebagai pembenah tanah."}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Asam Humat vs Asam Fulvat vs Pupuk Organik Biasa"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Asam humat dan asam fulvat merupakan fraksi dari senyawa humat yang dihasilkan melalui dekomposisi bahan organik. Asam humat memiliki berat molekul besar dan tidak larut dalam kondisi asam, sehingga lebih berperan dalam memperbaiki struktur tanah dan meningkatkan kapasitas tukar kation (KTK). Sementara itu, asam fulvat memiliki ukuran molekul lebih kecil, larut pada rentang pH yang luas, dan mampu menembus jaringan tanaman serta mengkelat ion logam. Pupuk organik biasa, seperti kompos atau pupuk kandang, mengandung campuran berbagai senyawa organik termasuk asam humat dan fulvat dalam jumlah kecil, tetapi tidak difraksinasi atau terkonsentrasi."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Perbedaan fungsional utama terletak pada mekanisme kerjanya. Asam humat bekerja terutama pada lingkungan tanah dengan meningkatkan agregasi tanah, retensi air, dan ketersediaan hara melalui pengikatan kation. Asam fulvat lebih aktif dalam fisiologi tanaman karena dapat diserap oleh akar dan daun, membantu transportasi nutrisi, serta merangsang metabolisme. Pupuk organik biasa memberikan manfaat jangka panjang sebagai sumber nutrisi makro dan mikro serta bahan organik, namun efeknya lebih lambat dan tidak terfokus seperti fraksi humat murni."}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"type": "text", "text": "Asam humat: molekul besar, tidak larut dalam asam, memperbaiki struktur tanah dan KTK."}]}, {"type": "list-item", "children": [{"type": "text", "text": "Asam fulvat: molekul kecil, larut di semua pH, mudah diserap tanaman, mengkelat logam."}]}, {"type": "list-item", "children": [{"type": "text", "text": "Pupuk organik biasa: campuran kompleks, kaya nutrisi, efek lambat, tidak terkonsentrasi."}]}, {"type": "list-item", "children": [{"type": "text", "text": "Asam humat/fulvat umumnya bersifat lebih stabil di tanah dibanding pupuk organik biasa."}]}, {"type": "list-item", "children": [{"type": "text", "text": "Mekanisme kelasi mineral lebih dominan pada asam fulvat, sedangkan asam humat dominan pada agregasi tanah."}]}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Cara Kerja dan Manfaat Asam Humat bagi Tanah dan Tanaman"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Asam humat bekerja secara multifaset dalam memperbaiki kondisi tanah dan mendukung pertumbuhan tanaman. Pertama, asam humat mengikat partikel tanah (lempung, pasir, dan debu) menjadi agregat yang lebih stabil. Proses ini memperbaiki struktur tanah menjadi lebih remah dan porous, sehingga aerasi dan drainase meningkat. Tanah menjadi tidak mudah padat, akar dapat menembus lebih dalam, dan air lebih mudah terserap serta ditahan. Perbaikan struktur ini juga mengurangi erosi dan pembentukan kerak permukaan."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Kedua, asam humat meningkatkan Kapasitas Tukar Kation (KTK) tanah. Molekul asam humat memiliki gugus fungsi yang dapat mengikat kation seperti kalsium, magnesium, kalium, dan amonium, kemudian melepaskannya secara bertahap ke larutan tanah. Hal ini membuat unsur hara lebih tersedia bagi akar tanaman dan mengurangi pencucian (leaching) akibat hujan atau irigasi. Selain itu, asam humat mampu mengikat (mengkelat) ion logam seperti besi, seng, tembaga, dan mangan, sehingga unsur mikro tetap larut dan dapat diserap tanaman, terutama di tanah dengan pH tinggi atau rendah."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Ketiga, asam humat mendorong aktivitas mikroorganisme tanah. Asam humat menyediakan sumber karbon dan energi bagi bakteri, fungi, dan aktinomisetes, serta menciptakan lingkungan yang kondusif (pH, suplai oksigen) untuk pertumbuhan mereka. Mikroba ini membantu dekomposisi bahan organik, siklus hara, dan produksi zat perangsang tumbuh alami. Selain itu, asam humat secara langsung merangsang perkembangan akar dengan meningkatkan permeabilitas membran sel akar, sehingga penyerapan air dan hara lebih efisien. Akar menjadi lebih panjang, bercabang, dan memiliki rambut akar yang lebih banyak."}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"type": "text", "text": "Memperbaiki struktur tanah menjadi gembur dan aerobik"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Meningkatkan kapasitas tukar kation (KTK) untuk retensi hara"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Mengkelat unsur hara mikro agar tetap tersedia bagi tanaman"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Mendukung populasi mikroorganisme tanah yang menguntungkan"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Merangsang pertumbuhan akar dan percabangan akar"}]}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Dosis dan Cara Aplikasi Asam Humat (Gambaran Umum)"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Asam humat dapat diaplikasikan melalui berbagai metode, seperti kocor tanah, semprot daun, dan fertigasi (irigasi tetes/leb). Prinsip umumnya adalah asam humat bekerja optimal ketika bersentuhan langsung dengan akar atau daun tanaman, namun dosis dan konsentrasi sangat bergantung pada jenis tanaman, kondisi tanah, dan konsentrasi produk. Sebagai panduan awal, aplikasi kocor tanah umumnya dilakukan pada area perakaran dengan volume larutan yang cukup untuk membasahi zona akar. Aplikasi semprot daun dilakukan pada pagi atau sore hari untuk menghindari penguapan cepat, dengan frekuensi disesuaikan fase pertumbuhan. Fertigasi memungkinkan distribusi merata melalui sistem irigasi, namun perlu diperhatikan kompatibilitas dengan pupuk lain."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Karena setiap produk asam humat memiliki konsentrasi dan formulasi berbeda, sangat penting untuk mengacu pada petunjuk spesifik pada kemasan produk yang digunakan. Faktor seperti pH air, suhu, dan kecepatan pengadukan juga mempengaruhi efektivitas. Untuk hasil optimal, konsultasikan dengan ahli agronomi atau panduan teknis dari produsen, terutama jika dikombinasikan dengan pupuk atau pestisida. Mulailah dengan dosis rendah pada area kecil untuk mengamati respons tanaman sebelum diaplikasikan secara luas."}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Asam Humat untuk Berbagai Komoditas"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Aplikasi asam humat perlu disesuaikan dengan jenis komoditas karena setiap tanaman memiliki kebutuhan hara dan respons yang berbeda terhadap perbaikan sifat tanah. Faktor seperti jenis tanah, iklim, dan sistem budidaya turut memengaruhi efektivitas asam humat. Oleh karena itu, dosis, waktu, dan metode aplikasi perlu dioptimalkan secara spesifik untuk masing-masing komoditas."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Berikut adalah beberapa komoditas utama yang umum diaplikasikan asam humat, dengan panduan khusus yang dapat disesuaikan berdasarkan kondisi setempat:"}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"type": "text", "text": "Padi"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Sawit"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Cabai"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Jagung"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Kopi"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Hortikultura"}]}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Asam Humat untuk Berbagai Kondisi Tanah"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Asam humat berperan penting dalam memperbaiki sifat fisik, kimia, dan biologi berbagai jenis tanah. Pada tanah berpasir, asam humat meningkatkan kapasitas menahan air dan unsur hara melalui pembentukan agregat dan peningkatan kapasitas tukar kation (KTK). Di tanah liat, asam humat membantu memperbaiki struktur tanah dengan mengurangi kepadatan dan meningkatkan aerasi serta drainase. Pada tanah gambut, asam humat berfungsi sebagai khelator logam dan penyangga pH, sehingga mengurangi toksisitas logam berat dan menstabilkan kondisi asam. Sementara itu, di tanah salin, asam humat dapat mengurangi efek buruk salinitas dengan mengikat ion natrium dan meningkatkan ketersediaan air. Di lahan kritis, asam humat mendorong pembentukan agregat stabil dan aktivitas mikroba, sehingga memulihkan produktivitas tanah secara bertahap."}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Cara Memilih Asam Humat Cair yang Baik"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Memilih asam humat cair yang baik memerlukan perhatian pada sumber bahan baku. Asam humat berkualitas berasal dari leonardit atau lignit yang teroksidasi secara alami, bukan dari gambut atau sumber lain yang tidak konsisten. Produsen yang transparan akan mencantumkan asal bahan baku pada label atau dokumen teknis. Pastikan produk telah melalui proses ekstraksi yang tepat untuk mempertahankan struktur molekul aktifnya."}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Konsistensi mutu dapat dinilai dari kelarutan dan stabilitas produk. Asam humat cair yang baik larut sempurna dalam air tanpa endapan berlebihan. Untuk membedakan produk asli dan palsu, perhatikan warna dan bau: produk asli cenderung berwarna cokelat kehitaman pekat dengan aroma tanah yang khas, bukan bau kimia menyengat. Hindari produk yang terlalu encer atau mengandung bahan pengisi seperti molase atau pewarna sintetis."}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"type": "text", "text": "Sumber bahan baku jelas (leonardit atau lignit teroksidasi)"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Konsistensi mutu (stabil antar batch, tidak menggumpal)"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Kelarutan tinggi (larut sempurna tanpa residu)"}]}, {"type": "list-item", "children": [{"type": "text", "text": "Membedakan asli vs palsu (warna, bau, tidak ada endapan berlebih)"}]}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Black Turbo: Asam Humat Cair dari Centra Biotech"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Black Turbo adalah asam humat cair dari Centra Biotech yang dirancang untuk mendukung pertanian Indonesia. Produk ini membantu memperbaiki struktur tanah, meningkatkan daya ikat air dan hara, serta mendorong aktivitas mikroba tanah secara alami. Dengan kandungan asam humat yang mudah larut, Black Turbo dapat digunakan pada berbagai jenis tanaman dan sistem irigasi. Untuk informasi lebih lanjut mengenai dosis dan aplikasi yang sesuai dengan kondisi lahan Anda, silakan berkonsultasi dengan tim teknis Centra Biotech."}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Panduan Asam Humat per Topik"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Telusuri panduan mendalam untuk tiap topik berikut:"}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/apa-itu-asam-humat-dan-manfaatnya-untuk-tanaman", "children": [{"type": "text", "text": "Apa itu asam humat dan manfaatnya untuk tanaman"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-dari-leonardite-vs-dari-gambut", "children": [{"type": "text", "text": "Asam humat dari leonardite vs gambut"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/perbedaan-asam-humat-dan-asam-fulvat", "children": [{"type": "text", "text": "Perbedaan asam humat dan asam fulvat"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/cara-kerja-asam-humat-meningkatkan-kesuburan-tanah", "children": [{"type": "text", "text": "Cara kerja asam humat meningkatkan kesuburan tanah"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-dan-peningkatan-ktk-tanah", "children": [{"type": "text", "text": "Asam humat dan peningkatan KTK tanah"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-dan-ph-tanah-hubungan-penting", "children": [{"type": "text", "text": "Asam humat dan pH tanah"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/dosis-dan-cara-aplikasi-asam-humat", "children": [{"type": "text", "text": "Dosis dan cara aplikasi asam humat"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-untuk-sawit-dosis-per-pokok-per-semester", "children": [{"type": "text", "text": "Asam humat cair untuk sawit"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-untuk-padi-dosis-dan-jadwal-aplikasi", "children": [{"type": "text", "text": "Asam humat cair untuk padi"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-untuk-cabai-panduan-pemupukan-lengkap", "children": [{"type": "text", "text": "Asam humat cair untuk cabai"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-untuk-jagung-meningkatkan-serapan-hara", "children": [{"type": "text", "text": "Asam humat cair untuk jagung"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-untuk-lahan-gambut", "children": [{"type": "text", "text": "Asam humat cair untuk lahan gambut"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-untuk-tanah-berpasir", "children": [{"type": "text", "text": "Asam humat untuk tanah berpasir"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/asam-humat-cair-terbaik-2026-rekomendasi-produk", "children": [{"type": "text", "text": "Asam humat cair terbaik: rekomendasi produk"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/cara-membedakan-asam-humat-cair-asli-dan-palsu", "children": [{"type": "text", "text": "Cara membedakan asam humat cair asli dan palsu"}]}]}, {"type": "list-item", "children": [{"type": "link", "url": "https://centrabiotechindonesia.com/id/blog/harga-asam-humat-cair-di-indonesia-perbandingan", "children": [{"type": "text", "text": "Harga asam humat cair di Indonesia"}]}]}]}, {"type": "heading", "level": 2, "children": [{"type": "text", "text": "Konsultasi Kebutuhan Asam Humat Anda"}]}, {"type": "paragraph", "children": [{"type": "text", "text": "Ingin menerapkan asam humat cair pada lahan Anda? Pelajari produk "}, {"type": "link", "url": "https://centrabiotechindonesia.com/id/produk-layanan/pertanian/blackturbo-asam-humat-cair", "children": [{"type": "text", "text": "Black Turbo Asam Humat Cair"}]}, {"type": "text", "text": " dari Centra Biotech Indonesia, atau hubungi tim kami untuk konsultasi agronomi."}]}]',
